function projectForDemo(d){const types=d.types.slice();if(types[0]!=="battery"&&types[0]!=="acsource"&&types[0]!=="threephase"&&types[0]!=="controlsource")types.unshift("battery");const components=types.map((type,i)=>({id:"C"+String(i+1).padStart(3,"0"),type,x:130+i*135,y:220+(i%2)*45,rotation:0,props:defaultProps(type,d.factor),pins:[]}));const wires=[];const pinCount={battery:2,resistor:2,lamp:2,led:2,switch:2,fuse:2,breaker:2,"circuit-breaker-3p":6,rcd:2,relay:4,contactor:12,motor:7,ground:1,terminal:2,multimeter:2,oscilloscope:2,acsource:2,threephase:3,controlsource:2,"pushbutton-no":2,capacitor:2,inductor:2,diode:2,zener:2,logic_and:3,logic_or:3,logic_not:2,arduino:8,gpio:1,sensor:1,buzzer:2,heater:2,socket:3,rail:0,wirelabel:1};const outPin=t=>pinCount[t]>1?1:0;for(let i=0;i<components.length-1;i++)wires.push({id:"W"+String(i+1).padStart(3,"0"),a:components[i].id+":"+outPin(components[i].type),b:components[i+1].id+":0",color:"#65d8ff",cableType:"standard",size:"1.5",gauge:"16",width:2.5});if(components.length>2&&components[0].type==="battery")wires.push({id:"W"+String(wires.length+1).padStart(3,"0"),a:components[components.length-1].id+":"+outPin(components[components.length-1].type),b:components[0].id+":0",color:"#ffbd69",cableType:"standard",size:"1.5",gauge:"16",width:2.5});return{format:"voltpro",version:2,metadata:{name:d.title,author:"VoltPRo Academy",created:new Date().toISOString(),learningGoal:d.goal,difficulty:d.level,source:"VoltPRo Academy Workbench"},mode:"schematic",components,wires,wireStyle:{color:"#65d8ff",cableType:"standard",size:"1.5",gauge:"16",width:2.5},panel:{rails:[],items:[],width:600,height:400},simulation:{running:false}}}
function defaultProps(type,f){const p={battery:{voltage:12*f},acsource:{voltage:230},threephase:{voltage:400},controlsource:{voltage:24},resistor:{resistance:330/f},lamp:{resistance:120/f},led:{forward:2,resistance:330/f},fuse:{rating:1},breaker:{rating:6},switch:{closed:1},motor:{resistance:24},capacitor:{capacitance:1e-6},inductor:{inductance:.01},relay:{coilVoltage:24,coilResistance:240,closed:0},contactor:{coilVoltage:230,coilResistance:82,closed:0},zener:{voltage:5.1},terminal:{label:"X1"},sensor:{value:50},arduino:{code:"blink"},gpio:{state:0},logic_and:{},logic_or:{},logic_not:{},multimeter:{mode:"voltage"},oscilloscope:{mode:"voltage"},ground:{},heater:{resistance:46},buzzer:{resistance:100},diode:{forward:.7},capacitor:{capacitance:1e-6}};return JSON.parse(JSON.stringify(p[type]||{}))}
