let selectedCalc=calcDefs[0];function calcValues(){const vals={};selectedCalc.fields.forEach(([key])=>{const el=$("calcFields").querySelector('[data-calc="'+key+'"]');const n=el&&el.value.trim()!==""?Number(el.value):null;vals[key]=Number.isFinite(n)?n:null});return vals}
function renderCalc(){const c=selectedCalc;$("calcFields").innerHTML=c.fields.map(([key,label,def])=>'<label>'+esc(label)+'<input type="number" step="any" data-calc="'+esc(key)+'" value="'+esc(def)+'" placeholder="Leave blank if unknown"></label>').join("");$("calcFormula").textContent=c.formula;$("calcExplanation").textContent="";$("calcResult").textContent="Enter values to calculate.";runCalc();$("calcFields").querySelectorAll("input").forEach(el=>el.addEventListener("input",runCalc))}
function runCalc(){const v=calcValues();try{const r=selectedCalc.run(v);$("calcResult").textContent=r.result;$("calcExplanation").textContent=r.explain;$("calcFormula").textContent=selectedCalc.formula}catch(e){$("calcResult").textContent="Check inputs."; $("calcExplanation").textContent="The calculator could not evaluate these values."}}
calcDefs.forEach(c=>$("calcSelect").insertAdjacentHTML("beforeend",'<option value="'+c.id+'">'+esc(c.name)+' · '+esc(c.category)+'</option>'));$("calcSelect").onchange=()=>{selectedCalc=calcDefs.find(c=>c.id===$("calcSelect").value)||calcDefs[0];renderCalc()};$("calcReset").onclick=renderCalc;$("calcCopy").onclick=()=>navigator.clipboard?.writeText($("calcResult").textContent+" | "+$("calcFormula").textContent).then(()=>{$("calcCopy").textContent="Copied";setTimeout(()=>$("calcCopy").textContent="Copy result",1200)}).catch(()=>{});
const $color=$("colorInput");function parseColor(raw){const s=raw.trim();let m=s.match(/^#?([0-9a-f]{3}|[0-9a-f]{4}|[0-9a-f]{6}|[0-9a-f]{8})$/i);if(m){let h=m[1];if(h.length===3||h.length===4)h=[...h].map(x=>x+x).join("");return{r:parseInt(h.slice(0,2),16),g:parseInt(h.slice(2,4),16),b:parseInt(h.slice(4,6),16),a:h.length===8?parseInt(h.slice(6,8),16):255}}m=s.match(/^rgba?\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})(?:\s*,\s*(0|1|0?\.\d+))?\s*\)$/i);if(m){const c=[+m[1],+m[2],+m[3]];if(c.some(x=>x>255))return null;return{r:c[0],g:c[1],b:c[2],a:m[4]===undefined?255:Math.round(+m[4]*255)}}return null}
function hex(c){return"#"+[c.r,c.g,c.b].map(x=>Math.round(x).toString(16).padStart(2,"0")).join("").toUpperCase()}
function rgbToHsl(c){const r=c.r/255,g=c.g/255,b=c.b/255,max=Math.max(r,g,b),min=Math.min(r,g,b),d=max-min;let h=0,s=0,l=(max+min)/2;if(d){s=d/(1-Math.abs(2*l-1));if(max===r)h=60*(((g-b)/d)%6);else if(max===g)h=60*((b-r)/d+2);else h=60*((r-g)/d+4);if(h<0)h+=360}return{h,s,l}}
function hslToRgb(h,s,l){h=((h%360)+360)%360;s=clamp(s,0,1);l=clamp(l,0,1);const c=(1-Math.abs(2*l-1))*s,x=c*(1-Math.abs((h/60)%2-1)),m=l-c/2;let r=0,g=0,b=0;if(h<60){r=c;g=x}else if(h<120){r=x;g=c}else if(h<180){g=c;b=x}else if(h<240){g=x;b=c}else if(h<300){r=x;b=c}else{r=c;b=x}return{r:Math.round((r+m)*255),g:Math.round((g+m)*255),b:Math.round((b+m)*255)}}
function luminance(c){const lin=v=>{v/=255;return v<=.04045?v/12.92:((v+.055)/1.055)**2.4};return .2126*lin(c.r)+.7152*lin(c.g)+.0722*lin(c.b)}
function contrast(a,b){const x=luminance(a),y=luminance(b);return(Math.max(x,y)+.05)/(Math.min(x,y)+.05)}
function setChannels(c){["R","G","B"].forEach(k=>$("channel"+k).value=c[k.toLowerCase()])}
function colorUpdate(fromChannels=false){let c;if(fromChannels){c={r:clamp(Number($("channelR").value)||0,0,255),g:clamp(Number($("channelG").value)||0,0,255),b:clamp(Number($("channelB").value)||0,0,255),a:255};$color.value=hex(c)}else c=parseColor($color.value);const valid=!!c;$("colorValidation").classList.toggle("invalid",!valid);$("colorValidation").textContent=valid?"Valid color · "+hex(c):"Invalid or incomplete HEX / RGB. Use #RGB, #RGBA, #RRGGBB, #RRGGBBAA or rgb().";if(!valid){$("colorSwatch").style.background="transparent";$("colorReadouts").innerHTML='<div class="aw-empty">Finish entering a valid colour value to update the calculations. Partial input is preserved.</div>';$("colorPalette").innerHTML="";$("colorPwm").innerHTML="";return}setChannels(c);const hsl=rgbToHsl(c),lum=luminance(c),black=contrast(c,{r:0,g:0,b:0}),white=contrast(c,{r:255,g:255,b:255});$("colorSwatch").style.background="rgba("+c.r+","+c.g+","+c.b+","+(c.a/255)+")";$("colorReadouts").innerHTML=[["HEX",hex(c)+(c.a<255?" / alpha "+c.a:"")],["RGB",c.r+", "+c.g+", "+c.b],["HSL",Math.round(hsl.h)+"°, "+Math.round(hsl.s*100)+"%, "+Math.round(hsl.l*100)+"%"],["LUMINANCE",lum.toFixed(3)],["CONTRAST VS BLACK",black.toFixed(2)+":1"],["CONTRAST VS WHITE",white.toFixed(2)+":1"]].map(r=>'<div class="aw-readout"><span>'+r[0]+'</span><b>'+esc(r[1])+'</b></div>').join("");const colors=[{name:"Base",c},{name:"Complement",c:hslToRgb(hsl.h+180,hsl.s,hsl.l)},{name:"Analog −30°",c:hslToRgb(hsl.h-30,hsl.s,hsl.l)},{name:"Analog +30°",c:hslToRgb(hsl.h+30,hsl.s,hsl.l)},{name:"Triad +120°",c:hslToRgb(hsl.h+120,hsl.s,hsl.l)},{name:"Triad +240°",c:hslToRgb(hsl.h+240,hsl.s,hsl.l)},{name:"Lighter",c:hslToRgb(hsl.h,hsl.s,Math.min(.92,hsl.l+.2))},{name:"Darker",c:hslToRgb(hsl.h,hsl.s,Math.max(.08,hsl.l-.2))}];$("colorPalette").innerHTML=colors.map(x=>'<button type="button" title="'+esc(x.name+" "+hex(x.c))+'" data-palette-color="'+hex(x.c)+'" style="background:'+hex(x.c)+'"><span>'+hex(x.c)+'</span></button>').join("");$("colorPalette").querySelectorAll("[data-palette-color]").forEach(b=>b.onclick=()=>{$color.value=b.dataset.paletteColor;colorUpdate()});$("colorPwm").innerHTML=[["R",c.r],["G",c.g],["B",c.b]].map(([k,v])=>'<div class="aw-pwm-row"><b>'+k+'</b><div class="aw-pwm-track"><i style="width:'+(v/255*100)+'%;background:'+(k==="R"?"#ff7777":k==="G"?"#70e7a8":"#67aaff")+'"></i></div><span>'+Math.round(v/255*1000)/10+'%</span></div>').join("");ledUpdate()}
$color.addEventListener("input",()=>colorUpdate());["R","G","B"].forEach(k=>$("channel"+k).addEventListener("input",()=>colorUpdate(true)));function ledUpdate(){const vs=Number($("ledSupply").value),vf=Number($("ledVf").value),ma=Number($("ledCurrent").value),I=ma/1000;let text="Check values";if(Number.isFinite(vs)&&Number.isFinite(vf)&&Number.isFinite(I)&&vs>vf&&I>0){const R=(vs-vf)/I,P=I*I*R;const standards=[10,12,15,18,22,27,33,39,47,56,68,82,100,120,150,180,220,270,330,390,470,560,680,820,1000,1200,1500,1800,2200,2700,3300,3900,4700,5600,6800,8200].map(x=>x);const preferred=standards.find(x=>x>=R)||null;$("ledResistor").textContent="R ≈ "+fmt(R,2)+" Ω"+(preferred? " · next listed "+preferred+" Ω":"");$("ledPower").textContent="Resistor dissipation ≈ "+fmt(P,3)+" W; target ≥ "+fmt(P*2,3)+" W (2× design margin)";return}$("ledResistor").textContent=text;$("ledPower").textContent="Supply must exceed forward voltage and current must be positive."}
["ledSupply","ledVf","ledCurrent"].forEach(id=>$(id).addEventListener("input",ledUpdate));colorUpdate();

