function wireUpdate(){const V=Number($("wireVoltage").value),I=Number($("wireCurrent").value),L=Number($("wireLength").value),A=Number($("wireSize").value),rho=$("wireMaterial").value==="Al"?.0282:.0175,max=Number($("wireMaxDrop").value),drop=I*2*L*rho/A,pct=V>0?drop/V*100:Infinity;const valid=V>0&&I>=0&&L>=0&&A>0&&max>0;$("wireResult").textContent=valid?"Voltage drop ≈ "+fmt(drop,4)+" V · "+fmt(pct,3)+" %":"Check voltage, current, length and cross-section."; $("wireDetails").textContent=valid?"Estimated loop resistance: "+fmt(2*L*rho/A,5)+" Ω · target "+max+"% · "+(pct<=max?"within target drop for this simplified model":"above target drop in this simplified model"):"Use positive voltage, cross-section and target percentage.";return{valid,V,I,L,A,rho,drop,pct}}
["wireVoltage","wireCurrent","wireLength","wireSize","wireMaterial","wireMaxDrop"].forEach(id=>$(id).addEventListener("input",wireUpdate));$("wireColor").addEventListener("input",()=>{});$("wireApply").onclick=()=>{const w=wireUpdate();if(!w.valid)return;const project={format:"voltpro",version:2,metadata:{name:"Wire Lab Settings",author:"VoltPRo Academy",created:new Date().toISOString()},mode:"schematic",components:[],wires:[],wireStyle:{color:$("wireColor").value,cableType:$("wireType").value,size:String($("wireSize").value),gauge:"16",width:2.5},panel:{rails:[],items:[],width:600,height:400},simulation:{running:false}};launchProject(project)};

async function loadToolIndex(){try{const r=await fetch("data/electrical-tool-index.json");if(!r.ok)throw Error("Tool index unavailable");const d=await r.json();const tools=d.tools||[];$("awToolCount").textContent=tools.length.toLocaleString();$("toolIndexBadge").textContent=tools.length.toLocaleString()+" entries";const cats=[...new Set(tools.map(t=>t.category))].sort();cats.forEach(c=>$("toolCategory").insertAdjacentHTML("beforeend",'<option>'+esc(c)+'</option>'));let page=0;const size=60;function render(){const q=$("toolSearch").value.toLowerCase().trim(),cat=$("toolCategory").value,list=tools.filter(t=>(cat==="all"||t.category===cat)&&(!q||(t.name+" "+t.category+" "+t.description).toLowerCase().includes(q)));const pages=Math.max(1,Math.ceil(list.length/size));page=clamp(page,0,pages-1);$("toolResults").textContent=list.length.toLocaleString()+" tools";$("toolPage").textContent="Page "+(page+1)+" / "+pages;$("toolPrev").disabled=page===0;$("toolNext").disabled=page>=pages-1;$("toolGrid").innerHTML=list.slice(page*size,(page+1)*size).map(t=>'<article class="aw-tool-item"><b>'+esc(t.name)+'</b><small>'+esc(t.category)+'</small><p>'+esc(t.description)+'</p></article>').join("")||'<div class="aw-empty">No matching tools.</div>'}["input","change"].forEach(ev=>["toolSearch","toolCategory"].forEach(id=>$(id).addEventListener(ev,()=>{page=0;render()})));$("toolPrev").onclick=()=>{page--;render()};$("toolNext").onclick=()=>{page++;render()};render()}catch(e){$("toolGrid").innerHTML='<div class="aw-empty">Could not load the curated tool index. Engineering calculators remain available above.</div>'}}
function downloadProject(p){const blob=new Blob([JSON.stringify(p,null,2)],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=(p.metadata?.name||"voltpro-project").replace(/[^a-z0-9_-]+/gi,"-").toLowerCase()+".voltpro";a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function launchProject(p){try{localStorage.setItem("voltpro-library-import",JSON.stringify(p));const w=window.open("simulator.html?libraryImport=1","_blank");if(!w){location.href="simulator.html?libraryImport=1";return}try{w.opener=null}catch{} }catch(e){alert("Could not prepare the project for the simulator: "+e.message)}}
